};

function buildTopicSelectionRules(subject: string): string {
  const subjectRule = SUBJECT_RULES[subject] ?? "";
  return `【トピック選択ルール - 厳守】
タグは少なく正確に。以下の手順で選択すること。

■ Step 1: まず問題の本質を一言で説明する
